"use client"

import * as React from "react"
import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox"
import { Icon } from "@iconify/react"

import { cn } from "@/lib/utils"

function Checkbox({
  className,
  indeterminate,
  ...props
}: CheckboxPrimitive.Root.Props) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      className={cn(
        "peer inline-flex items-center justify-center h-[1.125rem] w-[1.125rem] shrink-0 rounded-[0.3125rem]",
        "bg-card [box-shadow:var(--shadow-inset)]",
        "transition-[background,box-shadow] duration-fast",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40",
        "data-disabled:cursor-not-allowed data-disabled:opacity-50",
        "data-checked:[background:var(--pill-gradient)] data-checked:text-foreground data-checked:[box-shadow:var(--shadow-pill)]",
        "data-indeterminate:[background:var(--pill-gradient)] data-indeterminate:text-foreground data-indeterminate:[box-shadow:var(--shadow-pill)]",
        className
      )}
      indeterminate={indeterminate}
      {...props}
    >
      <CheckboxPrimitive.Indicator data-slot="checkbox-indicator" className="size-full flex items-center justify-center text-current">
        {indeterminate ? (
          <Icon icon="tabler:minus" className="h-3 w-3" />
        ) : (
          <Icon icon="tabler:check" className="h-3 w-3" />
        )}
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  )
}
Checkbox.displayName = "Checkbox"

export { Checkbox }
